    "Nim++/Clang": "./target/bin_benchmarks_clang_cpp",
    "Nim++/Clang/Danger": "./target/bin_benchmarks_clang_cpp_danger",
    "Nim/NLVM": "./target/bin_benchmarks_nlvm",
    "Nim/NLVM/Danger": "./target/bin_benchmarks_nlvm_danger",
    "Julia/Default": "julia --project=. --threads=16 benchmark.jl",
    "Julia/Max": "julia --project=. --threads=16 -O3 --check-bounds=no --math-mode=fast --inline=yes benchmark.jl",
    "Swift": "./.build/release/Benchmarks",
    "Swift/Unchecked": "./.build/release/Benchmarks",
    "Odin/Default": "target/bin_odin",
    "Odin/Opt": "target/bin_odin_optimized",
    "Odin/MaxPerf": "target/bin_odin_maxperf",
    "C3": "./build/prod",
    "C3/SingleModule": "./build/prod_single_module",
    "C3/Fast": "./build/fast",
    "C3/Fast/SingleModule": "./build/fast_single_module",
    "C3/Unsafe": "./build/unsafe",
    "Java/OpenJDK": "java   -Xmx2g   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Java/OpenJDK/Serial": "java   -Xmx512m   -XX:+UseSerialGC   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Java/OpenJDK/Opt": "java   -XX:+UseParallelGC   -XX:+UseLargePages   -XX:+AlwaysPreTouch   -XX:+UseCompressedOops   -XX:+OptimizeStringConcat   -XX:+UseStringDeduplication   -XX:+DisableExplicitGC   -XX:+UseCountedLoopSafepoints   -Xmx2g   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Java/GraalVM/JIT": "java   -Xmx2g   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Java/GraalVM/Serial": "java   -XX:+UseSerialGC   -Xmx512m   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Kotlin/JVM/Default": "java -Xmx2g -jar /src/kotlin/build/libs/benchmarks.jar",
    "Kotlin/JVM/Opt": "java   -XX:+UseG1GC   -Xms2g   -XX:+AlwaysPreTouch   -XX:+OptimizeStringConcat   -XX:+UseCompressedOops   -Xmx2g   -jar /src/kotlin/build/libs/benchmarks.jar",
    "Kotlin/JVM/Max": "java   -XX:+UseParallelGC   -Xms4g   -Xmx8g   -XX:+AlwaysPreTouch   -XX:+UseLargePages   -XX:+DisableExplicitGC   -jar /src/kotlin/build/libs/benchmarks.jar",
    "Kotlin/GraalVM/JIT": "java   -Xmx2g   -jar /src/kotlin/build/libs/benchmarks.jar",
    "Scala/JVM/Default": "java -Xmx2g -jar /src/scala/target/benchmark.jar",
    "Scala/JVM/Opt": "java   -XX:+UseG1GC   -Xms2g   -Xmx2g   -XX:+AlwaysPreTouch   -XX:+OptimizeStringConcat   -XX:+UseCompressedOops   -jar /src/scala/target/benchmark.jar",
    "Scala/JVM/Max": "java   -XX:+UseParallelGC   -Xms4g   -Xmx8g   -XX:+AlwaysPreTouch   -XX:+UseLargePages   -XX:+DisableExplicitGC   -Djava.security.egd=file:/dev/./urandom   -jar /src/scala/target/benchmark.jar",
    "Scala/GraalVM/JIT": "java   -Xmx2g   -jar /src/scala/target/benchmark.jar",
    "Dart/AOT": "./target/dart_benchmark",
    "Dart/JIT": "dart run main.dart",
    "TypeScript/Node/Default": "node --max-old-space-size=4096 /src/typescript/target/dist/index.js",
    "TypeScript/Node/Opt": "node   --max-old-space-size=4096   --max-semi-space-size=256   --optimize-for-size   /src/typescript/target/dist/index.js",
    "TypeScript/Bun/JIT": "bun run /src/typescript/src/index.ts",
    "TypeScript/Bun/Compiled": "bun run /src/typescript/target/dist-bun/index.js",
    "TypeScript/Deno/Default": "deno run   --allow-all   --v8-flags=--max-old-space-size=4096   /src/typescript/src/index.ts",
    "TypeScript/Deno/Turbo": "deno run   --allow-all   --v8-flags=\"--max-old-space-size=4096,--concurrent-recompilation\"   --no-check   /src/typescript/src/index.ts",
    "Python/PYPY": "pypy3 main.py",
    "Ruby/CRuby4/YJIT": "ruby --yjit main.rb",
    "Ruby/Truffle/JVM": "ruby main.rb",
    "Ruby/Spinel/Clang": "target/bin_spinel_clang",
    "PHP": "php -d opcache.enable=1 -d opcache.enable_cli=1 -d opcache.jit=tracing -d opcache.jit_buffer_size=256M -d memory_limit=-1 main.php",
    "JS/Node/Default": "node /src/javascript/index.js",
    "JS/Bun/JIT": "bun run /src/javascript/index.js",
    "JS/Deno/Default": "deno run   --allow-all   --v8-flags=--max-old-space-size=4096   /src/javascript/index.js"
